        public static void Open(Window owner,DeepSystemsContext ctx)
        {
            if(ctx==null)return;Load(ctx);Refresh(ctx);Window w=W(owner,"YOMI · VOIDΩ · UNKNOWN UNKNOWNS OBSERVATORY",1560,980);DockPanel root=Shell("VOIDΩ · UNKNOWN UNKNOWNS OBSERVATORY","The final civilization-layer observatory. It searches retained investigations for structural absences, monocultures, unchallenged assumptions, unresolved contradictions, underused lenses and theory-test debt. It can expose blind-spot candidates. It cannot prove that it found the things nobody has imagined.");
            TextBlock status=new TextBlock{Text="DEV13.37.30   ·   FINAL CIVILIZATION-LAYER RELEASE   ·   "+Snapshot.BlindSpots.Count+" blind-spot candidates   ·   "+Snapshot.Disagreements.Count+" disagreements   ·   Ctrl+Alt+V",Foreground=Accent,FontWeight=FontWeights.Bold,Margin=new Thickness(20,0,20,12)};DockPanel.SetDock(status,Dock.Top);root.Children.Add(status);
            ScrollViewer scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto};WrapPanel chambers=new WrapPanel{Margin=new Thickness(12)};scroll.Content=chambers;root.Children.Add(scroll);
            Portal(chambers,"VOID","BLIND-SPOT UNIVERSE","All detected absences and asymmetries, with observed structure separated from heuristic suspicion.",delegate{Refresh(ctx);OpenCollection(w,"BLIND-SPOT UNIVERSE",VisibleBlindSpots().Cast<object>().ToList(),"Candidate blind spots are navigation prompts, not omniscience claims.");});
            Portal(chambers,"TOP","HIGHEST-PRESSURE BLIND SPOTS","What most deserves skeptical attention next.",delegate{Refresh(ctx);OpenCollection(w,"HIGHEST-PRESSURE BLIND SPOTS",VisibleBlindSpots().OrderByDescending(x=>x.Priority).Take(128).Cast<object>().ToList(),"Priority is deterministic triage, not truth probability.");});
            Portal(chambers,"ABS","STRUCTURAL ABSENCE FIELD","Missing source lineage, missing civilization coverage, missing decision evidence and other directly observable absences.",delegate{Refresh(ctx);OpenCollection(w,"STRUCTURAL ABSENCE FIELD",VisibleBlindSpots().Where(x=>x.StructuralAbsence).Cast<object>().ToList(),"These are absences in retained structure, not proof that missing information exists outside it.");});
            Portal(chambers,"≈","HEURISTIC SUSPICION FIELD","Candidates inferred from sparse use, text cues or weak coverage. Every row remains visibly heuristic.",delegate{Refresh(ctx);OpenCollection(w,"HEURISTIC SUSPICION FIELD",VisibleBlindSpots().Where(x=>x.Heuristic).Cast<object>().ToList(),"Heuristics suggest where to look; they do not certify a blind spot.");});
