            Portal(chambers,"COV","CIVILIZATION COVERAGE MATRIX","Which specialist lenses actually appear in retained investigations and which are neglected or absent.",delegate{Refresh(ctx);OpenCollection(w,"CIVILIZATION COVERAGE MATRIX",Snapshot.Coverage.Cast<object>().ToList(),"Coverage is descriptive. An unused civilization may be irrelevant rather than missing.");});
