            Portal(chambers,"NOTE","VOID NOTEBOOK","Notes attached to blind spots, disagreements and theory-test identities.",delegate{OpenCollection(w,"VOID NOTEBOOK",Store.Notes.Cast<object>().ToList(),"Notes never mutate EXPΩ/METAΩ/SYNTHΩ authority stores.");});
